package com.collabspace.controller; import com.collabspace.entity.*;import com.collabspace.repository.*;import com.collabspace.service.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/channels/{channelId}/members") @RequiredArgsConstructor public class ChannelMemberController {private final ChannelRepository channels;private final ChannelMemberRepository members;private final WorkspaceMemberRepository wm;private final CurrentUserService current; @GetMapping public List<Map<String,Object>> list(@PathVariable UUID channelId){Channel c=channels.findById(channelId).orElseThrow();if(!members.existsByChannelIdAndUserId(channelId,current.get().getId()))throw new SecurityException("Forbidden");return members.findByChannelId(channelId).stream().map(m->Map.<String,Object>of("id",m.getUser().getId(),"username",m.getUser().getUsername(),"email",m.getUser().getEmail(),"status",m.getUser().getStatus().name(),"lastSeen",Objects.requireNonNullElse(m.getUser().getLastSeen(),""))).toList();} @PostMapping("/{userId}") public void add(@PathVariable UUID channelId,@PathVariable UUID userId){Channel c=channels.findById(channelId).orElseThrow();WorkspaceMember me=wm.findByWorkspaceIdAndUserId(c.getWorkspace().getId(),current.get().getId()).orElseThrow(()->new SecurityException("Forbidden"));if(me.getRole()==WorkspaceRole.MEMBER)throw new SecurityException("Admin permission required");WorkspaceMember target=wm.findByWorkspaceIdAndUserId(c.getWorkspace().getId(),userId).orElseThrow(()->new NoSuchElementException("User is not in workspace"));if(!members.existsByChannelIdAndUserId(channelId,userId))members.save(ChannelMember.builder().channel(c).user(target.getUser()).build());} @DeleteMapping("/{userId}") public void remove(@PathVariable UUID channelId,@PathVariable UUID userId){Channel c=channels.findById(channelId).orElseThrow();WorkspaceMember me=wm.findByWorkspaceIdAndUserId(c.getWorkspace().getId(),current.get().getId()).orElseThrow();if(me.getRole()==WorkspaceRole.MEMBER)throw new SecurityException("Admin permission required");members.deleteByChannelIdAndUserId(channelId,userId);}}